// @ts-check
/*
 * Astro config for the consumer-sidebar half of `sidebar-build-html.test.ts`
 * (C-004). It builds the EXAMPLE site's pages
 * (`astro build --root example --config <this file>`) with one difference from
 * `example/astro.config.mjs`: the site supplies its own `sidebar`. The toolkit
 * must render it as written.
 *
 * The sidebar is written so that every shaping rule would visibly change it:
 *   - a hand-written group lists a nested group BEFORE a link (shaping puts
 *     links first) and its links out of slug order;
 *   - an autogenerated group over `rhetoric/` keeps Starlight's own subgroup
 *     labels (the directory names) and placement (subgroups before links;
 *     shaping would use the index titles and put links first).
 *
 * The other options repeat the example's, because that config does not export
 * them. If the example gains an option its pages need, repeat it here.
 */
import { defineConfig } from 'astro/config';
import { readFileSync } from 'node:fs';
import { defineDocKittyIntegrations } from '@spec-kitty/doc-toolkit/config';
import { specKittyTheme } from '@spec-kitty/doc-toolkit/themes/spec-kitty/index.ts';

const BASE = '/doc-kitty';
const EXAMPLE = new URL('../../../../example/', import.meta.url);

const REDIRECTS = Object.fromEntries(
  Object.entries(JSON.parse(readFileSync(new URL('redirects.json', EXAMPLE), 'utf8'))).map(
    ([from, to]) => [from, `${BASE}${to}`],
  ),
);

export default defineConfig({
  site: 'https://spec-kitty.github.io',
  base: BASE,
  outDir: `./${process.env.DK_OUTDIR}`,
  redirects: REDIRECTS,
  integrations: defineDocKittyIntegrations({
    title: 'DocKitty Example',
    description: 'A minimal docsite built with DocKitty.',
    base: BASE,
    social: { github: 'https://github.com/spec-kitty/doc-kitty' },
    theme: specKittyTheme,
    sidebar: [
      {
        label: 'Hand-written',
        items: [
          {
            label: 'nested-group',
            items: [
              { label: 'Second chapter', link: '/rhetoric/book-one/chapter-02/' },
              { label: 'First chapter', link: '/rhetoric/book-one/chapter-01/' },
            ],
          },
          { label: 'Link after the group', link: '/guides/getting-started/' },
        ],
      },
      // `docs/` prefix: ADR-0029 (Starlight matches against the project-relative path).
      { label: 'rhetoric as generated', autogenerate: { directory: 'docs/rhetoric' } },
    ],
    diagrams: true,
    markua: true,
    indexBasename: ['README', 'index'],
  }),
});
